quiz.prompt:
seviyeBul is called with the thresholds 300 / 250 / 600 / 500. The level starts as NORMAL. Six measurements arrive in order, and after each step the letter of the new level (N, U or T) is printed. What does this code print?

```
enum Seviye { NORMAL, UYARI, TEHLIKE };

Seviye seviyeBul(Seviye simdiki, int deger,
                 int uyariAc, int uyariKapat,
                 int tehlikeAc, int tehlikeKapat) {
  if (simdiki == NORMAL) {
    if (deger >= tehlikeAc) return TEHLIKE;
    if (deger >= uyariAc) return UYARI;
    return NORMAL;
  }
  if (simdiki == UYARI) {
    if (deger >= tehlikeAc) return TEHLIKE;
    if (deger < uyariKapat) return NORMAL;
    return UYARI;
  }
  if (deger < tehlikeKapat) {
    return (deger >= uyariKapat) ? UYARI : NORMAL;
  }
  return TEHLIKE;
}

void setup() {
  Serial.begin(9600);
  int olcum[] = {320, 280, 240, 650, 520, 480};
  Seviye s = NORMAL;
  for (int i = 0; i < 6; i++) {
    s = seviyeBul(s, olcum[i], 300, 250, 600, 500);
    Serial.print(s == NORMAL ? 'N' : (s == UYARI ? 'U' : 'T'));
  }
}
```
